INSERT INTO actor_role (role_code, role_name, is_human, responsibilities) VALUES ('BUSINESS_REQUESTER', 'Business requester', 1, 'Raises POs, confirms receipts, answers price/receipt/quantity queries, approves non-PO invoices');
INSERT INTO actor_role (role_code, role_name, is_human, responsibilities) VALUES ('PROCESS_OWNER', 'Process owner', 1, 'Owns the AP policy; decides policy exceptions (invoice before PO, PO quantity overrun)');
INSERT INTO actor_role (role_code, role_name, is_human, responsibilities) VALUES ('APPROVER', 'Approver', 1, 'Approves invoices by amount band and level (L1, L2, L3)');
INSERT INTO actor_role (role_code, role_name, is_human, responsibilities) VALUES ('OPERATIONS_ANALYST', 'Operations analyst', 1, 'Works the AP queues: capture review, duplicates, validation, tax, payment watch');
INSERT INTO actor_role (role_code, role_name, is_human, responsibilities) VALUES ('SYSTEM_ADMINISTRATOR', 'System administrator', 1, 'Maintains the vendor master, the policy file, runs and the audit trail');
INSERT INTO actor_role (role_code, role_name, is_human, responsibilities) VALUES ('SYSTEM', 'AP automation engine', 0, 'Automated capture, matching, routing, auto-approval and scheduling');
