-- AP automation seed: master data, inbox and engine output
-- Generated by `python -m invoice_ap export` from the spec and the layer CSVs.
PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;

CREATE TABLE actor_role (
  role_code TEXT NOT NULL CHECK ((role_code IN ('BUSINESS_REQUESTER', 'PROCESS_OWNER', 'APPROVER', 'OPERATIONS_ANALYST', 'SYSTEM_ADMINISTRATOR', 'SYSTEM')) OR role_code IS NULL),
  role_name TEXT NOT NULL,
  is_human INTEGER NOT NULL CHECK ((is_human IN (0, 1)) OR is_human IS NULL),
  responsibilities TEXT NOT NULL,
  PRIMARY KEY (role_code)
);

CREATE TABLE app_user (
  user_id TEXT NOT NULL,
  display_name TEXT NOT NULL,
  role_code TEXT NOT NULL CHECK ((role_code IN ('BUSINESS_REQUESTER', 'PROCESS_OWNER', 'APPROVER', 'OPERATIONS_ANALYST', 'SYSTEM_ADMINISTRATOR', 'SYSTEM')) OR role_code IS NULL),
  responsibility TEXT NOT NULL CHECK ((responsibility IN ('SYSTEM_USER', 'VENDOR_MASTER_OWNER', 'PLATFORM_ADMIN', 'POLICY_OWNER', 'AP_ANALYST', 'REQUESTER', 'COST_CENTER_MANAGER', 'FINANCE_CONTROLLER', 'CHIEF_FINANCIAL_OFFICER')) OR responsibility IS NULL),
  cost_center TEXT CHECK ((cost_center IN ('OPERATIONS', 'MANUFACTURING', 'IT', 'FACILITIES', 'LOGISTICS', 'CORPORATE')) OR cost_center IS NULL),
  approval_level TEXT CHECK ((approval_level IN ('L1', 'L2', 'L3')) OR approval_level IS NULL),
  email TEXT NOT NULL,
  active_from TEXT NOT NULL CHECK ((active_from = date(active_from)) OR active_from IS NULL),
  PRIMARY KEY (user_id),
  UNIQUE (display_name),
  UNIQUE (email),
  FOREIGN KEY (role_code) REFERENCES actor_role (role_code)
);

CREATE TABLE payment_terms (
  terms_code TEXT NOT NULL CHECK ((terms_code IN ('NET15', 'NET30', 'NET45', 'NET60')) OR terms_code IS NULL),
  net_days INTEGER NOT NULL CHECK ((net_days >= 1) AND (net_days <= 90) OR net_days IS NULL),
  description TEXT NOT NULL,
  PRIMARY KEY (terms_code)
);

CREATE TABLE tax_code (
  tax_code TEXT NOT NULL CHECK ((tax_code IN ('GST0', 'GST5', 'GST12', 'GST18', 'EXEMPT')) OR tax_code IS NULL),
  rate_pct NUMERIC NOT NULL CHECK ((rate_pct >= 0.00) AND (rate_pct <= 40.00) OR rate_pct IS NULL),
  tax_category TEXT NOT NULL CHECK ((tax_category IN ('STANDARD', 'REDUCED', 'ZERO_RATED', 'EXEMPT')) OR tax_category IS NULL),
  description TEXT NOT NULL,
  valid_from TEXT NOT NULL CHECK ((valid_from = date(valid_from)) OR valid_from IS NULL),
  valid_to TEXT CHECK ((valid_to = date(valid_to)) OR valid_to IS NULL),
  PRIMARY KEY (tax_code)
);

CREATE TABLE sku (
  sku_id TEXT NOT NULL,
  description TEXT NOT NULL,
  category TEXT NOT NULL CHECK ((category IN ('RAW_MATERIALS', 'ELECTRICAL', 'MRO_SPARES', 'PACKAGING', 'IT_HARDWARE', 'OFFICE_SUPPLIES', 'SAFETY_EQUIPMENT', 'CANTEEN_SUPPLIES')) OR category IS NULL),
  uom TEXT NOT NULL CHECK ((uom IN ('EA', 'BOX', 'PACK', 'SET', 'KG', 'L', 'M', 'HR', 'MONTH', 'JOB')) OR uom IS NULL),
  default_tax_code TEXT NOT NULL CHECK ((default_tax_code IN ('GST0', 'GST5', 'GST18', 'EXEMPT')) OR default_tax_code IS NULL),
  reference_price NUMERIC NOT NULL CHECK ((reference_price >= 0.01) OR reference_price IS NULL),
  lead_time_min_days INTEGER NOT NULL CHECK ((lead_time_min_days >= 1) OR lead_time_min_days IS NULL),
  lead_time_max_days INTEGER NOT NULL,
  PRIMARY KEY (sku_id),
  UNIQUE (description),
  FOREIGN KEY (default_tax_code) REFERENCES tax_code (tax_code)
);

CREATE TABLE vendor (
  vendor_id TEXT NOT NULL,
  vendor_name TEXT NOT NULL,
  tax_registration_id TEXT NOT NULL,
  segment TEXT NOT NULL CHECK ((segment IN ('GOODS', 'SERVICES')) OR segment IS NULL),
  category TEXT NOT NULL CHECK ((category IN ('RAW_MATERIALS', 'ELECTRICAL', 'MRO_SPARES', 'PACKAGING', 'IT_HARDWARE', 'OFFICE_SUPPLIES', 'SAFETY_EQUIPMENT', 'CANTEEN_SUPPLIES', 'FACILITY_SERVICES', 'PROFESSIONAL_SERVICES', 'IT_SERVICES', 'LOGISTICS_SERVICES')) OR category IS NULL),
  tier TEXT NOT NULL CHECK ((tier IN ('STRATEGIC', 'CORE', 'TAIL')) OR tier IS NULL),
  payment_terms_code TEXT NOT NULL CHECK ((payment_terms_code IN ('NET15', 'NET30', 'NET45', 'NET60')) OR payment_terms_code IS NULL),
  preferred_channel TEXT NOT NULL CHECK ((preferred_channel IN ('PORTAL', 'EDI', 'EMAIL', 'SCAN')) OR preferred_channel IS NULL),
  remit_email TEXT NOT NULL,
  onboarded_date TEXT NOT NULL CHECK ((onboarded_date = date(onboarded_date)) OR onboarded_date IS NULL),
  snapshot_status TEXT NOT NULL CHECK ((snapshot_status IN ('ACTIVE', 'BLOCKED', 'CLOSED')) OR snapshot_status IS NULL),
  created_by TEXT NOT NULL,
  PRIMARY KEY (vendor_id),
  UNIQUE (vendor_name),
  UNIQUE (tax_registration_id),
  UNIQUE (remit_email),
  FOREIGN KEY (payment_terms_code) REFERENCES payment_terms (terms_code),
  FOREIGN KEY (created_by) REFERENCES app_user (user_id)
);

CREATE TABLE vendor_status_history (
  vsh_id TEXT NOT NULL,
  vendor_id TEXT NOT NULL,
  seq INTEGER NOT NULL CHECK ((seq >= 1) OR seq IS NULL),
  from_status TEXT CHECK ((from_status IN ('ACTIVE', 'BLOCKED', 'CLOSED')) OR from_status IS NULL),
  to_status TEXT NOT NULL CHECK ((to_status IN ('ACTIVE', 'BLOCKED', 'CLOSED')) OR to_status IS NULL),
  effective_date TEXT NOT NULL CHECK ((effective_date = date(effective_date)) OR effective_date IS NULL),
  recorded_at TEXT NOT NULL CHECK ((substr(recorded_at, 1, 19) = strftime('%Y-%m-%dT%H:%M:%S', substr(recorded_at, 1, 19))) OR recorded_at IS NULL),
  actor_role TEXT NOT NULL CHECK ((actor_role IN ('SYSTEM_ADMINISTRATOR')) OR actor_role IS NULL),
  actor_id TEXT NOT NULL,
  reason_code TEXT NOT NULL CHECK ((reason_code IN ('ONBOARDED', 'KYC_DOCUMENTS_EXPIRED', 'KYC_RENEWED', 'RELATIONSHIP_ENDED')) OR reason_code IS NULL),
  PRIMARY KEY (vsh_id),
  UNIQUE (vendor_id, seq),
  FOREIGN KEY (vendor_id) REFERENCES vendor (vendor_id),
  FOREIGN KEY (actor_id) REFERENCES app_user (user_id)
);

CREATE TABLE purchase_order (
  po_id TEXT NOT NULL,
  vendor_id TEXT NOT NULL,
  requester_id TEXT NOT NULL,
  cost_center TEXT NOT NULL CHECK ((cost_center IN ('OPERATIONS', 'MANUFACTURING', 'IT', 'FACILITIES', 'LOGISTICS', 'CORPORATE')) OR cost_center IS NULL),
  po_date TEXT NOT NULL CHECK ((po_date = date(po_date)) OR po_date IS NULL),
  currency TEXT NOT NULL CHECK ((currency IN ('INR')) OR currency IS NULL),
  payment_terms_code TEXT NOT NULL CHECK ((payment_terms_code IN ('NET15', 'NET30', 'NET45', 'NET60')) OR payment_terms_code IS NULL),
  line_count INTEGER NOT NULL CHECK ((line_count >= 1) AND (line_count <= 8) OR line_count IS NULL),
  total_net_amount NUMERIC NOT NULL CHECK ((total_net_amount >= 0.00) OR total_net_amount IS NULL),
  total_tax_amount NUMERIC NOT NULL CHECK ((total_tax_amount >= 0.00) OR total_tax_amount IS NULL),
  total_gross_amount NUMERIC NOT NULL CHECK ((total_gross_amount >= 0.00) OR total_gross_amount IS NULL),
  snapshot_status TEXT NOT NULL CHECK ((snapshot_status IN ('ISSUED', 'PARTIALLY_RECEIVED', 'RECEIVED')) OR snapshot_status IS NULL),
  PRIMARY KEY (po_id),
  FOREIGN KEY (vendor_id) REFERENCES vendor (vendor_id),
  FOREIGN KEY (requester_id) REFERENCES app_user (user_id),
  FOREIGN KEY (payment_terms_code) REFERENCES payment_terms (terms_code)
);

CREATE TABLE purchase_order_line (
  po_line_id TEXT NOT NULL,
  po_id TEXT NOT NULL,
  line_number INTEGER NOT NULL CHECK ((line_number >= 1) AND (line_number <= 8) OR line_number IS NULL),
  sku_id TEXT NOT NULL,
  description TEXT NOT NULL,
  uom TEXT NOT NULL CHECK ((uom IN ('EA', 'BOX', 'PACK', 'SET', 'KG', 'L', 'M', 'HR', 'MONTH', 'JOB')) OR uom IS NULL),
  ordered_qty NUMERIC NOT NULL CHECK ((ordered_qty >= 0.01) OR ordered_qty IS NULL),
  unit_price NUMERIC NOT NULL CHECK ((unit_price >= 0.01) OR unit_price IS NULL),
  tax_code TEXT NOT NULL CHECK ((tax_code IN ('GST0', 'GST5', 'GST18', 'EXEMPT')) OR tax_code IS NULL),
  tax_rate_pct NUMERIC NOT NULL,
  line_net_amount NUMERIC NOT NULL CHECK ((line_net_amount >= 0.00) OR line_net_amount IS NULL),
  line_tax_amount NUMERIC NOT NULL CHECK ((line_tax_amount >= 0.00) OR line_tax_amount IS NULL),
  line_gross_amount NUMERIC NOT NULL CHECK ((line_gross_amount >= 0.00) OR line_gross_amount IS NULL),
  promised_delivery_date TEXT NOT NULL CHECK ((promised_delivery_date = date(promised_delivery_date)) OR promised_delivery_date IS NULL),
  snapshot_received_qty NUMERIC NOT NULL CHECK ((snapshot_received_qty >= 0) OR snapshot_received_qty IS NULL),
  snapshot_open_qty NUMERIC NOT NULL CHECK ((snapshot_open_qty >= 0) OR snapshot_open_qty IS NULL),
  PRIMARY KEY (po_line_id),
  UNIQUE (po_id, line_number),
  FOREIGN KEY (po_id) REFERENCES purchase_order (po_id),
  FOREIGN KEY (sku_id) REFERENCES sku (sku_id),
  FOREIGN KEY (tax_code) REFERENCES tax_code (tax_code)
);

CREATE TABLE goods_receipt (
  grn_id TEXT NOT NULL,
  po_id TEXT NOT NULL,
  vendor_id TEXT NOT NULL,
  received_date TEXT NOT NULL CHECK ((received_date = date(received_date)) OR received_date IS NULL),
  posted_at TEXT NOT NULL CHECK ((substr(posted_at, 1, 19) = strftime('%Y-%m-%dT%H:%M:%S', substr(posted_at, 1, 19))) OR posted_at IS NULL),
  received_by TEXT NOT NULL,
  delivery_note_number TEXT NOT NULL,
  line_count INTEGER NOT NULL CHECK ((line_count >= 1) OR line_count IS NULL),
  snapshot_status TEXT NOT NULL CHECK ((snapshot_status IN ('POSTED')) OR snapshot_status IS NULL),
  PRIMARY KEY (grn_id),
  FOREIGN KEY (po_id) REFERENCES purchase_order (po_id),
  FOREIGN KEY (vendor_id) REFERENCES vendor (vendor_id),
  FOREIGN KEY (received_by) REFERENCES app_user (user_id)
);

CREATE TABLE goods_receipt_line (
  grn_line_id TEXT NOT NULL,
  grn_id TEXT NOT NULL,
  po_line_id TEXT NOT NULL,
  line_number INTEGER NOT NULL CHECK ((line_number >= 1) OR line_number IS NULL),
  received_qty NUMERIC NOT NULL CHECK ((received_qty >= 0.01) OR received_qty IS NULL),
  uom TEXT NOT NULL CHECK ((uom IN ('EA', 'BOX', 'PACK', 'SET', 'KG', 'L', 'M', 'HR', 'MONTH', 'JOB')) OR uom IS NULL),
  cumulative_received_qty NUMERIC NOT NULL CHECK ((cumulative_received_qty >= 0) OR cumulative_received_qty IS NULL),
  receipt_type TEXT NOT NULL CHECK ((receipt_type IN ('PARTIAL', 'FULL', 'OVER')) OR receipt_type IS NULL),
  PRIMARY KEY (grn_line_id),
  UNIQUE (grn_id, line_number),
  UNIQUE (grn_id, po_line_id),
  FOREIGN KEY (grn_id) REFERENCES goods_receipt (grn_id),
  FOREIGN KEY (po_line_id) REFERENCES purchase_order_line (po_line_id)
);

CREATE TABLE erp_event (
  event_id TEXT NOT NULL,
  entity_type TEXT NOT NULL CHECK ((entity_type IN ('PURCHASE_ORDER', 'GOODS_RECEIPT')) OR entity_type IS NULL),
  entity_id TEXT NOT NULL,
  seq INTEGER NOT NULL CHECK ((seq >= 1) OR seq IS NULL),
  from_status TEXT CHECK ((from_status IN ('ISSUED', 'PARTIALLY_RECEIVED', 'RECEIVED', 'POSTED')) OR from_status IS NULL),
  to_status TEXT NOT NULL CHECK ((to_status IN ('ISSUED', 'PARTIALLY_RECEIVED', 'RECEIVED', 'POSTED')) OR to_status IS NULL),
  event_at TEXT NOT NULL CHECK ((substr(event_at, 1, 19) = strftime('%Y-%m-%dT%H:%M:%S', substr(event_at, 1, 19))) OR event_at IS NULL),
  actor_role TEXT NOT NULL CHECK ((actor_role IN ('BUSINESS_REQUESTER', 'SYSTEM')) OR actor_role IS NULL),
  actor_id TEXT NOT NULL,
  reason_code TEXT NOT NULL CHECK ((reason_code IN ('PO_ISSUED', 'GOODS_RECEIVED', 'GRN_POSTED')) OR reason_code IS NULL),
  ref_id TEXT,
  PRIMARY KEY (event_id),
  UNIQUE (entity_type, entity_id, seq),
  FOREIGN KEY (actor_id) REFERENCES app_user (user_id)
);

CREATE TABLE intake_manifest (
  doc_id TEXT NOT NULL,
  intake_seq INTEGER NOT NULL CHECK ((intake_seq >= 1) AND (intake_seq <= 999999) OR intake_seq IS NULL),
  channel TEXT NOT NULL CHECK ((channel IN ('PORTAL', 'EDI', 'EMAIL', 'SCAN')) OR channel IS NULL),
  file_format TEXT NOT NULL CHECK ((file_format IN ('PORTAL_JSON', 'EDI_FLAT', 'EMAIL_TEXT', 'OCR_TEXT')) OR file_format IS NULL),
  received_at TEXT NOT NULL CHECK ((substr(received_at, 1, 19) = strftime('%Y-%m-%dT%H:%M:%S', substr(received_at, 1, 19))) OR received_at IS NULL),
  sender_address TEXT NOT NULL,
  sender_vendor_id TEXT,
  file_path TEXT NOT NULL,
  file_sha256 TEXT NOT NULL,
  file_bytes INTEGER NOT NULL CHECK ((file_bytes >= 1) OR file_bytes IS NULL),
  PRIMARY KEY (doc_id),
  UNIQUE (intake_seq),
  UNIQUE (file_path),
  FOREIGN KEY (sender_vendor_id) REFERENCES vendor (vendor_id)
);

CREATE TABLE captured_invoice (
  invoice_id TEXT NOT NULL,
  doc_id TEXT NOT NULL,
  channel TEXT NOT NULL CHECK ((channel IN ('PORTAL', 'EDI', 'EMAIL', 'SCAN')) OR channel IS NULL),
  captured_at TEXT NOT NULL CHECK ((substr(captured_at, 1, 19) = strftime('%Y-%m-%dT%H:%M:%S', substr(captured_at, 1, 19))) OR captured_at IS NULL),
  capture_status TEXT NOT NULL CHECK ((capture_status IN ('OK', 'LOW_CONFIDENCE')) OR capture_status IS NULL),
  min_field_confidence NUMERIC NOT NULL CHECK ((min_field_confidence >= 0) AND (min_field_confidence <= 1) OR min_field_confidence IS NULL),
  vendor_name TEXT NOT NULL,
  vendor_tax_id TEXT NOT NULL,
  vendor_id TEXT,
  vendor_invoice_number TEXT,
  normalized_invoice_number TEXT,
  invoice_date TEXT CHECK ((invoice_date = date(invoice_date)) OR invoice_date IS NULL),
  po_number TEXT,
  po_id TEXT,
  attention_user_id TEXT,
  currency TEXT NOT NULL CHECK ((currency IN ('INR')) OR currency IS NULL),
  header_net_amount NUMERIC CHECK ((header_net_amount >= 0.00) OR header_net_amount IS NULL),
  header_tax_amount NUMERIC CHECK ((header_tax_amount >= 0.00) OR header_tax_amount IS NULL),
  header_gross_amount NUMERIC CHECK ((header_gross_amount >= 0.00) OR header_gross_amount IS NULL),
  line_count INTEGER NOT NULL CHECK ((line_count >= 1) OR line_count IS NULL),
  PRIMARY KEY (invoice_id),
  UNIQUE (doc_id),
  FOREIGN KEY (doc_id) REFERENCES intake_manifest (doc_id),
  FOREIGN KEY (vendor_id) REFERENCES vendor (vendor_id),
  FOREIGN KEY (po_id) REFERENCES purchase_order (po_id),
  FOREIGN KEY (attention_user_id) REFERENCES app_user (user_id)
);

CREATE TABLE captured_invoice_line (
  invoice_line_id TEXT NOT NULL,
  invoice_id TEXT NOT NULL,
  line_number INTEGER NOT NULL CHECK ((line_number >= 1) OR line_number IS NULL),
  po_line_number INTEGER CHECK ((po_line_number >= 1) OR po_line_number IS NULL),
  po_line_id TEXT,
  sku_id TEXT,
  description TEXT NOT NULL,
  uom TEXT NOT NULL CHECK ((uom IN ('EA', 'BOX', 'PACK', 'SET', 'KG', 'L', 'M', 'HR', 'MONTH', 'JOB')) OR uom IS NULL),
  quantity NUMERIC NOT NULL CHECK ((quantity >= 0) OR quantity IS NULL),
  unit_price NUMERIC NOT NULL CHECK ((unit_price >= 0.00) OR unit_price IS NULL),
  line_net_amount NUMERIC NOT NULL CHECK ((line_net_amount >= 0.00) OR line_net_amount IS NULL),
  tax_code TEXT NOT NULL CHECK ((tax_code IN ('GST0', 'GST5', 'GST12', 'GST18', 'EXEMPT')) OR tax_code IS NULL),
  tax_amount NUMERIC NOT NULL CHECK ((tax_amount >= 0.00) OR tax_amount IS NULL),
  min_field_confidence NUMERIC NOT NULL CHECK ((min_field_confidence >= 0) AND (min_field_confidence <= 1) OR min_field_confidence IS NULL),
  PRIMARY KEY (invoice_line_id),
  UNIQUE (invoice_id, line_number),
  FOREIGN KEY (invoice_id) REFERENCES captured_invoice (invoice_id),
  FOREIGN KEY (po_line_id) REFERENCES purchase_order_line (po_line_id),
  FOREIGN KEY (sku_id) REFERENCES sku (sku_id),
  FOREIGN KEY (tax_code) REFERENCES tax_code (tax_code)
);

CREATE TABLE extraction_field (
  extraction_field_id TEXT NOT NULL,
  doc_id TEXT NOT NULL,
  invoice_id TEXT NOT NULL,
  invoice_line_id TEXT,
  field_name TEXT NOT NULL,
  raw_text TEXT,
  normalized_value TEXT,
  confidence NUMERIC NOT NULL CHECK ((confidence >= 0) AND (confidence <= 1) OR confidence IS NULL),
  method TEXT NOT NULL CHECK ((method IN ('STRUCTURED', 'SEGMENT', 'LABEL_EXACT', 'LABEL_SYNONYM', 'PATTERN', 'OCR_REPAIRED', 'NOT_FOUND')) OR method IS NULL),
  is_low_confidence INTEGER NOT NULL CHECK ((is_low_confidence IN (0, 1)) OR is_low_confidence IS NULL),
  PRIMARY KEY (extraction_field_id),
  UNIQUE (doc_id, invoice_line_id, field_name),
  FOREIGN KEY (doc_id) REFERENCES intake_manifest (doc_id),
  FOREIGN KEY (invoice_id) REFERENCES captured_invoice (invoice_id),
  FOREIGN KEY (invoice_line_id) REFERENCES captured_invoice_line (invoice_line_id)
);

CREATE TABLE match_result (
  invoice_line_id TEXT NOT NULL,
  invoice_id TEXT NOT NULL,
  po_line_id TEXT,
  price_status TEXT NOT NULL CHECK ((price_status IN ('EXACT', 'WITHIN_TOLERANCE', 'OUT_OF_TOLERANCE', 'NOT_EVALUATED')) OR price_status IS NULL),
  po_unit_price NUMERIC CHECK ((po_unit_price >= 0.00) OR po_unit_price IS NULL),
  invoice_unit_price NUMERIC CHECK ((invoice_unit_price >= 0.00) OR invoice_unit_price IS NULL),
  price_variance_pct NUMERIC,
  price_tolerance_pct NUMERIC,
  qty_status TEXT NOT NULL CHECK ((qty_status IN ('OK', 'EXCEEDS_RECEIVED', 'EXCEEDS_PO', 'NO_RECEIPT', 'NOT_EVALUATED')) OR qty_status IS NULL),
  ordered_qty NUMERIC CHECK ((ordered_qty >= 0) OR ordered_qty IS NULL),
  received_qty NUMERIC CHECK ((received_qty >= 0) OR received_qty IS NULL),
  prior_invoiced_qty NUMERIC CHECK ((prior_invoiced_qty >= 0) OR prior_invoiced_qty IS NULL),
  invoiced_qty NUMERIC CHECK ((invoiced_qty >= 0) OR invoiced_qty IS NULL),
  max_qty_vs_po NUMERIC CHECK ((max_qty_vs_po >= 0) OR max_qty_vs_po IS NULL),
  tax_status TEXT NOT NULL CHECK ((tax_status IN ('OK', 'WITHIN_ROUNDING', 'CODE_MISMATCH', 'AMOUNT_MISMATCH', 'NOT_EVALUATED')) OR tax_status IS NULL),
  po_tax_code TEXT CHECK ((po_tax_code IN ('GST0', 'GST5', 'GST12', 'GST18', 'EXEMPT')) OR po_tax_code IS NULL),
  expected_tax_amount NUMERIC CHECK ((expected_tax_amount >= 0.00) OR expected_tax_amount IS NULL),
  line_match_status TEXT NOT NULL CHECK ((line_match_status IN ('MATCHED', 'MATCHED_WITHIN_TOLERANCE', 'PRICE_VARIANCE', 'QTY_MISMATCH', 'MISSING_RECEIPT', 'TAX_MISMATCH', 'NOT_APPLICABLE', 'NOT_EVALUATED')) OR line_match_status IS NULL),
  rule_ids TEXT,
  PRIMARY KEY (invoice_line_id),
  FOREIGN KEY (invoice_line_id) REFERENCES captured_invoice_line (invoice_line_id),
  FOREIGN KEY (invoice_id) REFERENCES captured_invoice (invoice_id),
  FOREIGN KEY (po_line_id) REFERENCES purchase_order_line (po_line_id),
  FOREIGN KEY (po_tax_code) REFERENCES tax_code (tax_code)
);

CREATE TABLE match_allocation (
  allocation_id TEXT NOT NULL,
  invoice_line_id TEXT NOT NULL,
  grn_line_id TEXT NOT NULL,
  allocated_qty NUMERIC NOT NULL CHECK ((allocated_qty >= 0.01) OR allocated_qty IS NULL),
  allocation_seq INTEGER NOT NULL CHECK ((allocation_seq >= 1) OR allocation_seq IS NULL),
  PRIMARY KEY (allocation_id),
  UNIQUE (invoice_line_id, grn_line_id),
  FOREIGN KEY (invoice_line_id) REFERENCES captured_invoice_line (invoice_line_id),
  FOREIGN KEY (grn_line_id) REFERENCES goods_receipt_line (grn_line_id)
);

CREATE TABLE duplicate_pair (
  duplicate_pair_id TEXT NOT NULL,
  invoice_id TEXT NOT NULL,
  original_invoice_id TEXT NOT NULL,
  match_type TEXT NOT NULL CHECK ((match_type IN ('EXACT', 'NUMBER_REUSE', 'CONTENT')) OR match_type IS NULL),
  matched_keys TEXT,
  PRIMARY KEY (duplicate_pair_id),
  UNIQUE (invoice_id),
  FOREIGN KEY (invoice_id) REFERENCES captured_invoice (invoice_id),
  FOREIGN KEY (original_invoice_id) REFERENCES captured_invoice (invoice_id)
);

CREATE TABLE policy_version (
  policy_version TEXT NOT NULL,
  policy_id TEXT NOT NULL,
  effective_from TEXT NOT NULL CHECK ((effective_from = date(effective_from)) OR effective_from IS NULL),
  as_of_date TEXT NOT NULL CHECK ((as_of_date = date(as_of_date)) OR as_of_date IS NULL),
  sha256 TEXT NOT NULL,
  PRIMARY KEY (policy_version)
);

CREATE TABLE ap_exception (
  exception_id TEXT NOT NULL,
  invoice_id TEXT NOT NULL,
  invoice_line_id TEXT,
  exception_type TEXT NOT NULL CHECK ((exception_type IN ('EXT_LOW_CONFIDENCE', 'DUPLICATE_EXACT', 'DUPLICATE_NUMBER_REUSE', 'DUPLICATE_SUSPECTED', 'VENDOR_NOT_FOUND', 'VENDOR_SENDER_MISMATCH', 'VENDOR_CLOSED', 'VENDOR_BLOCKED', 'PO_NOT_FOUND', 'VENDOR_PO_MISMATCH', 'INVOICE_DATE_IN_FUTURE', 'INVOICE_BEFORE_PO', 'HEADER_TOTAL_MISMATCH', 'LINE_AMOUNT_MISMATCH', 'TAX_CODE_INVALID', 'TAX_CODE_MISMATCH', 'TAX_AMOUNT_MISMATCH', 'PO_LINE_UNMATCHED', 'MISSING_RECEIPT', 'QTY_EXCEEDS_PO', 'QTY_EXCEEDS_RECEIVED', 'PRICE_VARIANCE', 'VENDOR_NOT_PAYABLE', 'PAYMENT_DUE_DATE_PASSED')) OR exception_type IS NULL),
  severity TEXT NOT NULL CHECK ((severity IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')) OR severity IS NULL),
  blocking INTEGER NOT NULL CHECK ((blocking IN (0, 1)) OR blocking IS NULL),
  is_primary INTEGER NOT NULL CHECK ((is_primary IN (0, 1)) OR is_primary IS NULL),
  rule_id TEXT NOT NULL,
  policy_version TEXT NOT NULL,
  expected_value TEXT,
  actual_value TEXT,
  variance TEXT,
  tolerance TEXT,
  related_invoice_id TEXT,
  assigned_role TEXT NOT NULL CHECK ((assigned_role IN ('BUSINESS_REQUESTER', 'PROCESS_OWNER', 'APPROVER', 'OPERATIONS_ANALYST', 'SYSTEM_ADMINISTRATOR')) OR assigned_role IS NULL),
  assigned_user_id TEXT NOT NULL,
  queue TEXT NOT NULL CHECK ((queue IN ('AP_CAPTURE_REVIEW', 'AP_DUPLICATES', 'AP_VALIDATION', 'AP_TAX', 'PAYMENT_WATCH', 'PO_QUERIES', 'RECEIPT_CONFIRMATION', 'PRICE_REVIEW', 'POLICY_EXCEPTIONS', 'VENDOR_MASTER')) OR queue IS NULL),
  created_at TEXT NOT NULL CHECK ((substr(created_at, 1, 19) = strftime('%Y-%m-%dT%H:%M:%S', substr(created_at, 1, 19))) OR created_at IS NULL),
  sla_due_date TEXT NOT NULL CHECK ((sla_due_date = date(sla_due_date)) OR sla_due_date IS NULL),
  status_as_of TEXT NOT NULL CHECK ((status_as_of IN ('OPEN', 'CLOSED')) OR status_as_of IS NULL),
  resolution_code TEXT,
  is_overdue_as_of INTEGER NOT NULL CHECK ((is_overdue_as_of IN (0, 1)) OR is_overdue_as_of IS NULL),
  PRIMARY KEY (exception_id),
  FOREIGN KEY (invoice_id) REFERENCES captured_invoice (invoice_id),
  FOREIGN KEY (invoice_line_id) REFERENCES captured_invoice_line (invoice_line_id),
  FOREIGN KEY (policy_version) REFERENCES policy_version (policy_version),
  FOREIGN KEY (related_invoice_id) REFERENCES captured_invoice (invoice_id),
  FOREIGN KEY (assigned_user_id) REFERENCES app_user (user_id)
);

CREATE TABLE approval (
  approval_id TEXT NOT NULL,
  invoice_id TEXT NOT NULL,
  level TEXT NOT NULL CHECK ((level IN ('AUTO', 'REQ', 'L1', 'L2', 'L3')) OR level IS NULL),
  sequence INTEGER NOT NULL CHECK ((sequence >= 1) OR sequence IS NULL),
  approval_band TEXT NOT NULL,
  approver_role TEXT NOT NULL CHECK ((approver_role IN ('SYSTEM', 'BUSINESS_REQUESTER', 'APPROVER')) OR approver_role IS NULL),
  approver_user_id TEXT NOT NULL,
  requested_at TEXT NOT NULL CHECK ((substr(requested_at, 1, 19) = strftime('%Y-%m-%dT%H:%M:%S', substr(requested_at, 1, 19))) OR requested_at IS NULL),
  decided_at TEXT CHECK ((substr(decided_at, 1, 19) = strftime('%Y-%m-%dT%H:%M:%S', substr(decided_at, 1, 19))) OR decided_at IS NULL),
  status_as_of TEXT NOT NULL CHECK ((status_as_of IN ('PENDING', 'APPROVED', 'REJECTED')) OR status_as_of IS NULL),
  rule_id TEXT NOT NULL,
  policy_version TEXT NOT NULL,
  PRIMARY KEY (approval_id),
  UNIQUE (invoice_id, level),
  UNIQUE (invoice_id, sequence),
  FOREIGN KEY (invoice_id) REFERENCES captured_invoice (invoice_id),
  FOREIGN KEY (approver_user_id) REFERENCES app_user (user_id),
  FOREIGN KEY (policy_version) REFERENCES policy_version (policy_version)
);

CREATE TABLE payment (
  payment_id TEXT NOT NULL,
  invoice_id TEXT NOT NULL,
  vendor_id TEXT NOT NULL,
  amount NUMERIC NOT NULL CHECK ((amount >= 0.01) OR amount IS NULL),
  currency TEXT NOT NULL CHECK ((currency IN ('INR')) OR currency IS NULL),
  payment_method TEXT NOT NULL CHECK ((payment_method IN ('NEFT', 'RTGS')) OR payment_method IS NULL),
  due_date TEXT NOT NULL CHECK ((due_date = date(due_date)) OR due_date IS NULL),
  scheduled_date TEXT NOT NULL CHECK ((scheduled_date = date(scheduled_date)) OR scheduled_date IS NULL),
  created_at TEXT NOT NULL CHECK ((substr(created_at, 1, 19) = strftime('%Y-%m-%dT%H:%M:%S', substr(created_at, 1, 19))) OR created_at IS NULL),
  paid_at TEXT CHECK ((substr(paid_at, 1, 19) = strftime('%Y-%m-%dT%H:%M:%S', substr(paid_at, 1, 19))) OR paid_at IS NULL),
  status_as_of TEXT NOT NULL CHECK ((status_as_of IN ('SCHEDULED', 'PAID')) OR status_as_of IS NULL),
  due_date_passed INTEGER NOT NULL CHECK ((due_date_passed IN (0, 1)) OR due_date_passed IS NULL),
  policy_version TEXT NOT NULL,
  PRIMARY KEY (payment_id),
  UNIQUE (invoice_id),
  FOREIGN KEY (invoice_id) REFERENCES captured_invoice (invoice_id),
  FOREIGN KEY (vendor_id) REFERENCES vendor (vendor_id),
  FOREIGN KEY (policy_version) REFERENCES policy_version (policy_version)
);

CREATE TABLE invoice_decision (
  invoice_id TEXT NOT NULL,
  status_as_of TEXT NOT NULL CHECK ((status_as_of IN ('RECEIVED', 'CAPTURED', 'ON_HOLD', 'REJECTED', 'PENDING_APPROVAL', 'APPROVED', 'PAYMENT_READY', 'PAID')) OR status_as_of IS NULL),
  match_status TEXT NOT NULL CHECK ((match_status IN ('MATCHED', 'MATCHED_WITHIN_TOLERANCE', 'PRICE_VARIANCE', 'QTY_MISMATCH', 'MISSING_RECEIPT', 'TAX_MISMATCH', 'NOT_APPLICABLE', 'NOT_EVALUATED')) OR match_status IS NULL),
  issue_types TEXT,
  primary_issue TEXT NOT NULL CHECK ((primary_issue IN ('EXT_LOW_CONFIDENCE', 'DUPLICATE_EXACT', 'DUPLICATE_NUMBER_REUSE', 'DUPLICATE_SUSPECTED', 'VENDOR_NOT_FOUND', 'VENDOR_SENDER_MISMATCH', 'VENDOR_CLOSED', 'VENDOR_BLOCKED', 'PO_NOT_FOUND', 'VENDOR_PO_MISMATCH', 'INVOICE_DATE_IN_FUTURE', 'INVOICE_BEFORE_PO', 'HEADER_TOTAL_MISMATCH', 'LINE_AMOUNT_MISMATCH', 'TAX_CODE_INVALID', 'TAX_CODE_MISMATCH', 'TAX_AMOUNT_MISMATCH', 'PO_LINE_UNMATCHED', 'MISSING_RECEIPT', 'QTY_EXCEEDS_PO', 'QTY_EXCEEDS_RECEIVED', 'PRICE_VARIANCE', 'VENDOR_NOT_PAYABLE', 'PAYMENT_DUE_DATE_PASSED', 'NONE')) OR primary_issue IS NULL),
  blocked INTEGER NOT NULL CHECK ((blocked IN (0, 1)) OR blocked IS NULL),
  duplicate_of_invoice_id TEXT,
  approval_band TEXT,
  approval_levels TEXT,
  payment_ready INTEGER NOT NULL CHECK ((payment_ready IN (0, 1)) OR payment_ready IS NULL),
  payment_id TEXT,
  decided_at TEXT NOT NULL CHECK ((substr(decided_at, 1, 19) = strftime('%Y-%m-%dT%H:%M:%S', substr(decided_at, 1, 19))) OR decided_at IS NULL),
  policy_version TEXT NOT NULL,
  rule_ids TEXT,
  PRIMARY KEY (invoice_id),
  FOREIGN KEY (invoice_id) REFERENCES captured_invoice (invoice_id),
  FOREIGN KEY (duplicate_of_invoice_id) REFERENCES captured_invoice (invoice_id),
  FOREIGN KEY (payment_id) REFERENCES payment (payment_id),
  FOREIGN KEY (policy_version) REFERENCES policy_version (policy_version)
);

CREATE TABLE ap_event (
  event_id TEXT NOT NULL,
  entity_type TEXT NOT NULL CHECK ((entity_type IN ('INVOICE', 'EXCEPTION', 'APPROVAL', 'PAYMENT')) OR entity_type IS NULL),
  entity_id TEXT NOT NULL,
  invoice_id TEXT NOT NULL,
  seq INTEGER NOT NULL CHECK ((seq >= 1) OR seq IS NULL),
  from_status TEXT CHECK ((from_status IN ('RECEIVED', 'CAPTURED', 'ON_HOLD', 'REJECTED', 'PENDING_APPROVAL', 'APPROVED', 'PAYMENT_READY', 'PAID', 'OPEN', 'CLOSED', 'PENDING', 'APPROVED', 'REJECTED', 'SCHEDULED', 'PAID')) OR from_status IS NULL),
  to_status TEXT NOT NULL CHECK ((to_status IN ('RECEIVED', 'CAPTURED', 'ON_HOLD', 'REJECTED', 'PENDING_APPROVAL', 'APPROVED', 'PAYMENT_READY', 'PAID', 'OPEN', 'CLOSED', 'PENDING', 'APPROVED', 'REJECTED', 'SCHEDULED', 'PAID')) OR to_status IS NULL),
  event_at TEXT NOT NULL CHECK ((substr(event_at, 1, 19) = strftime('%Y-%m-%dT%H:%M:%S', substr(event_at, 1, 19))) OR event_at IS NULL),
  actor_role TEXT NOT NULL CHECK ((actor_role IN ('BUSINESS_REQUESTER', 'PROCESS_OWNER', 'APPROVER', 'OPERATIONS_ANALYST', 'SYSTEM_ADMINISTRATOR', 'SYSTEM')) OR actor_role IS NULL),
  actor_id TEXT NOT NULL,
  rule_id TEXT,
  reason TEXT,
  policy_version TEXT NOT NULL,
  PRIMARY KEY (event_id),
  UNIQUE (entity_type, entity_id, seq),
  FOREIGN KEY (invoice_id) REFERENCES captured_invoice (invoice_id),
  FOREIGN KEY (actor_id) REFERENCES app_user (user_id),
  FOREIGN KEY (policy_version) REFERENCES policy_version (policy_version)
);

COMMIT;
